# ScrollView

- 내부의 여러 뷰들을 스크롤 가능하게 담는 뷰

### Vertical
- ScrollView는 기본적으로 수직 방향이다.
- VStack, ForEach를 활용하여 반복되는 동일한 뷰를 표현할 수 있다.
```swift
ScrollView { // 수직 방향 스크롤 뷰
	VStack {
		ForEach(0..<20) { index in
			Rectangle()
				.fill(Color.blue)
				.frame(height: 200)
		}
	}
}
```
### Horizontal
- `axes` 파라미터를 전달하여 ScrollView를 수평 방형으로 변경할 수 있다.
- `showsIndicators` 파라미터를 전달하여 스크롤바를 숨길 수 있다.
```swift
// 수평 방향 스크롤 뷰, 스크롤 바 숨김
ScrollView(.horizontal, showsIndicators: false, content: {
	HStack {
		ForEach(0..<20) { index in
			Rectangle()
				.fill(Color.blue)
				.frame(width: 300)
		}
	}
})
```

# ForEach
- 한 개 이상의 뷰를 반복할 수 있는 뷰

### 단순 반복
- 반복할 범위(횟수)를 지정해주고 반복할 뷰를 작성하여 원하는 만큼 뷰를 반복한다.
```swift
VStack {
	ForEach(0..<10) { index in // 반복 횟수 지정
		Text("Hi, my index is \(index)") // 반복할 뷰
	}
}
```

### Array 활용
- Array를 활용하여 반복할 횟수와 반복할 데이터를 전달한다.
- `.indices`는 컬렉션의 인덱스 범위를 나타내는 `Range<Int>`를 반환한다.
- `id: \.self`는 SwiftUI가 Array의 각 요소를 고유하게 식별할 수 있도록 한다.
```swift
struct ForEachStudy: View {

    let data: [String] = ["Hi", "Hello", "Hey"]

    var body: some View {
        VStack {
            ForEach(data.indices, id: \.self) { index in // Array 갯수 만큼 반복
                Text("\(index) is \(data[index])") // 반복 순서 별 Array 데이터 활용
            }
        }
    }
}
```

# Init, Enum
- 뷰 내부에 변수를 생성하고, Enum을 활용하여 초기화하여 뷰의 재사용성 향상

### 프로퍼티 기본값
- 뷰(구조체)의 재사용성을 높이기 위해 `title`, `backgroundColor`이라는 변수(프로퍼티)를 생성한다.
- 생성한 프로퍼티에 기본값을 할당한다.
```swift
struct TestView: View {

    // 프로퍼티 기본값 할당
    let backgroundColor: Color = .red
    let title: String = "Apple"

    var body: some View {
        VStack {
            Text(title)
                .font(.largeTitle)
                .foregroundColor(.white)
        }
        .frame(width: 150, height: 150)
        .background(backgroundColor)
        .cornerRadius(30)
    }
}
struct TestView_Previews: PreviewProvider {
    static var previews: some View {
        TestView() // 인스턴스 생성
    }
}
```

### 이니셜라이저 Init
- 프로퍼티 기본값을 지정하지 않을 경우, 이니셜라이저 `init`을 이용해 인스턴스가 갖어야 할 초기값을 전달한다.
- `self`는 현재의 인스턴스를 가르키므로 `self.backgroundColor`는 인스턴스 뷰 내부의 `let backgroundColor: Color`를 가르킨다.
- SwiftUI에서는 이니셜라이저를 따로 작성하지 않아도 자동으로 초기화가 진행된다.
```swift
struct TestView: View {

    let backgroundColor: Color
    let title: String

    // 이니셜라이저
    init(backgroundColor: Color, title: String) {
        self.backgroundColor = backgroundColor
        self.title = title
    }

    var body: some View {
        VStack {
            Text(title)
                .font(.largeTitle)
                .foregroundColor(.white)
        }
        .frame(width: 150, height: 150)
        .background(backgroundColor)
        .cornerRadius(30)
    }
}

struct TestView_Previews: PreviewProvider {
    static var previews: some View {
        TestView(backgroundColor: .red, title: "Apple") // 인스턴스를 생성하며 초기값 전달
    }
}
```
- 관련 있는 프로퍼티끼리 연관지어서 초기화 할 수 있다.
```swift
struct TestView: View {

    let backgroundColor: Color
    let title: String

    init(title: String) {
        self.title = title
        //title에 따라 backgroundColor 초기화
        if title == "Apple" {
            self.backgroundColor = .red
        } else {
            self.backgroundColor = .orange
        }
    }

    var body: some View {
        VStack {
            Text(title)
                .font(.largeTitle)
                .foregroundColor(.white)
        }
        .frame(width: 150, height: 150)
        .background(backgroundColor)
        .cornerRadius(30)
    }
}

struct TestView_Previews: PreviewProvider {
    static var previews: some View {
        TestView(title: "Orage") // 인스턴스를 생성하며 초기값 전달
    }
}
```

### 열거형 Enum
- 연관된 프로퍼티끼리 열거형 `enum`을 활용하여 타입을 정의하고, 제한된 파라미터 내에서 초기화 진행할 수 있다.
```swift
struct TestView: View {

    let backgroundColor: Color
    let title: String

    // 연관된 프로퍼티들의 케이스를 타입으로 지정
    enum Fruit {
        case apple
        case orange
        case grape
    }

    init(fruit: Fruit) { // 제한된 파라미터로 초기화 진행
	    // 전달 받은 파라미터에 따라 모든 프로퍼티 초기화
        if fruit == .apple {
            self.title = "Apple"
            self.backgroundColor = .red
        } else if fruit == .orange {
            self.title = "Orange"
            self.backgroundColor = .orange
        } else {
            self.title = "Grape"
            self.backgroundColor = .purple
        }
    }

    var body: some View {
        VStack {
            Text(title)
                .font(.largeTitle)
                .foregroundColor(.white)
        }
        .frame(width: 150, height: 150)
        .background(backgroundColor)
        .cornerRadius(30)
    }
}

struct TestView_Previews: PreviewProvider {
    static var previews: some View {
    	VStack {
        	TestView(fruit: .grape) // 인스턴스 생성 후 grape 케이스의 초기화 진행
			TestView(fruit: .apple) // 인스턴스 생성 후 apple 케이스의 초기화 진행
    	}
    }
}
```

### 조건문
1. if-else
* 조건을 지정하고 해당 조건이 true이면 코드 실행
* 조건 값에는 Bool 타입의 값만 위치해야하고, 조건을 감싸는 소괄호는 생략 가능
```swift
if 조건 {
    /* 실행 구문 */
} else if 조건 {
    /* 실행 구문 */
} else {
    /* 실행 구문 */
}
```
* 만약 확인한 조건이 true가 아니라면 else를 실행
```swift
let testScore = 75

if testScore > 80 {
    print("Your grade is A!")
} else if testScore > 60 {
    print("Your grade is B!")
} else {
    print("Your grade is C!")
}

// Your grade is B!
```
2. switch
* 각 case 별로 다른 코드를 실행시킬 때 사용
* 각 case 내부에는 반드시 실행할 코드 필요
* 한정적인 값(enum의 case 등)이 비교값이 아닌 한 default 구문 반드시 작성
```swift
switch 비교값 {
case 패턴:
    /* 실행 구문 */
default:
    /* 실행 구문 */
}
```
* case에 break를 추가하지 않아도 해당 코드가 실행되면 자동으로 break
* fallthrough 키워드를 추가하면 break 무시
* 쉼표를 사용하여 한 case에 여러 패턴 작성 가능
```swift
let testScore = 80

switch testScore {
case 100:
    print("Your are excellent!")
case 80..<100:
    print("Your grade is A!")
case 60..<80:
    print("Your grade is B!")
case 0..<60:
    print("Your grade is C!")
    fallthrough
default:
    print("Study hard!")
}
```

### 반복문
1. for-in
* for-in 구문의 기본 형태
```swift
for item in items {
    /* 실행 구문 */
}
```
* 컬렉션 타입을 활용한 for-in 구문
```swift
var integersArray = [2, 4, 6]
for integer in integersArray {
    print(integer)
}
// 2
// 4
// 6
// (3번 반복 실행)

let englishDictionary = ["elephant": "코끼리", "lion": "사자"]
for (english, korean) in englishDictionary {
    print("\(english): \(korean)")
}
// elephant: 코끼리
// lion: 사자
// (2번 반복 실행)
// Dictionary의 item은 key와 value로 구성된 튜플 타입
```
* 튜플 타입(Tuple) : 여러가지 타입의 복수 값들을 그룹화한 단일 값
2. while
* while 구문의 기본 형태
```swift
while 조건 {
    /* 실행 구문 */
}
// 조건에는 반드시 boolean 값
```
* 컬렉션 타입을 활용한 while 구문
```swift
var integersArray = [2, 4, 6]

while integersArray.count > 1 {
    integersArray.removeLast()
}
// [2, 4]
// [2]
// (2번 반복 실행)
```
3. repeat-while
* repeat-while 구문의 기본 형태
```swift
repeat {
    /* 실행 구문 */
} while 조건
// 조건에는 반드시 boolean 값
```
* 컬렉션 타입을 활용한 repeat-while 구문
```swift
var integersArray = [2, 4, 6]

repeat {
    integersArray.removeLast()
} while integersArray.count > 1
// [2, 4]
// [2]
// (2번 반복 실행)
```

### 컬렉션 타입
1. Array
* 순서(인덱스)가 있는 멤버를 가진 리스트 형태의 컬렉션 타입
```swift
var integersArray: Array<Int> = Array<Int>()

// 여러 형태로 변형 가능
// var integersArray: Array<Int> = [Int]()
// var integersArray: Array<Int> = []
// var integersArray: [Int] = Array<Int>()
// var integersArray: [Int] = [Int]()
// var integersArray: [Int] = []
// var integersArray = [Int]()
// var integersArray = Array<Int>()
```
* 메소드 등 여러가지 형태로 Array 활용
```swift
var integersArray: Array<Int> = []

// Array에 멤버 추가
integersArray.append(3) // [3]
integersArray.append(10) // [3, 10]

// Array에서의 멤버 확인
integersArray.contains(3) // true
integersArray.contains(5) // false

// Array의 멤버 교체
integersArray[0] = 7 // 0번째 멤버 7로 교체

// Array의 멤버 수 확인
integersArray.count // 2

// Array의 멤버 삭제
integersArray.remove(at: 0) // 0번째 멤버 삭제
integersArray.removeLast() // 마지막 멤버 삭제
integersArray.removeAll() // 모든 멤버 삭제

// 수정 불가 Array(멤버 추가, 삭제 불가)
let immutableArray = [1, 2, 3]
```
2. Dictionary
* 키(key)와 값(value)의 쌍으로 이루어진 컬렉션 타입
```swift
var englishDictionary: Dictionary<String, String> = Dictionary<String, String>()

// 여러 형태로 변형 가능
// var englishDictionary: Dictionary<String, String> = Dictionary<String, String>()
// var englishDictionary: Dictionary<String, String> = [:]
// var englishDictionary: [String: String] = Dictionary<String, String>()
// var englishDictionary: [String: String] = [String: String]()
// var englishDictionary: [String: String] = [:]
// var englishDictionary = Dictionary<String, String>()
// var englishDictionary = [String: String]()
```
* 메소드 등 여러가지 형태로 Dictionary 활용
```swift
var englishDictionary: Dictionary<String, String> = [:]

// 키에 해당하는 값 
englishDictionary["elephant"] = "코끼리"
englishDictionary["lion"] = "사자"

// 키에 해당하는 값 할당
englishDictionary["elephant"] = "코끼리" // ["elephant": "코끼리"]
englishDictionary["lion"] = "사자" // ["lion": "사자", "elephant": "코끼리"]

// 키에 해당하는 값 변경
englishDictionary["lion"] = "호랑이" // ["lion": "호랑이", "elephant": "코끼리"]

// 키에 해당하는 값 제거
englishDictionary.removeValue(forKey: "lion") // ["elephant": "코끼리"]
englishDictionary["elephant"] = nil // [:]

// 수정 불가 Dictionary(값 추가, 변경, 삭제 불가)
let initalizedDictionary: [String: String] = ["A": "a", "B": "b"]

// "A"라는 키에 해당하는 값이 없을 수 있으므로 String 타입의 값이 나올 것이라는 보장이 없음으로 컴파일 오류
let someValue: String = initalizedDictionary["A"]
```
3. Set
* 순서가 없고, 중복된 멤버가 없는 컬렉션 타입
* 집합과 비슷한 개념
```swift
var integersSet: Set<Int> = Set<Int>() // []
integersSet.insert(2) // [2]
integersSet.insert(4) // [2, 4]
integersSet.insert(6) // [2, 4, 6]
integersSet.insert(6) // [2, 4, 6]
// 중복된 데이터는 입력되지 않음

// Set에서의 멤버 확인
integersSet.contains(2) // true
integersSet.contains(3) // false

// Set에서 멤버 삭제
integersSet.remove(4) // [2, 6]
integersSet.removeFirst() // [6]

// Set의 멤버 수 확인
integersSet.count // 1
```
* 두 Set간의 집합연산이 가능
```swift
let setA: Set<Int> = [1, 2, 3, 4, 5]
let setB: Set<Int> = [2, 4, 6 ,8, 10]

// 합집합
let union: Set<Int> = setA.union(setB) // [2, 5, 6, 4, 10 , 1, 3, 8]

// 합집합 오름차순 정렬(Array)
let sortedUnion: [Int] = union.sorted() // [1, 2, 3, 4, 5, 6, 8, 10]

// 교집합
let intersection: Set<Int> = setA.intersection(setB) // [2, 4]

// 차집합
let subtractiong: Set<Int> = setA.subtracting(setB) // [1, 3, 5]
```
